package com.ahdi.ninety.app;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.graphics.Typeface;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;

public class MainActivity extends Activity {
    LinearLayout root, content, rewardsBox; GridLayout grid; TextView dayTitle, status, streak, progress, rewardTitle; Button markBtn;
    final int GREEN=Color.rgb(22,124,102), BG=Color.rgb(247,243,234), DARK=Color.rgb(35,48,43), MUTED=Color.rgb(93,105,99), GOLD=Color.rgb(180,128,37);
    @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG); if(Build.VERSION.SDK_INT>=23)getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR); build(); if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},9); ReminderScheduler.schedule(this);}
    TextView tv(String s,float sp,int col,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(col);t.setGravity(Gravity.CENTER);t.setTypeface(Typeface.DEFAULT,bold?Typeface.BOLD:Typeface.NORMAL);t.setPadding(12,8,12,8);t.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));return t;}
    GradientDrawable bg(int color,float r){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(r);return g;}
    Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setTextColor(Color.WHITE);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setAllCaps(false);b.setBackground(bg(GREEN,28));b.setPadding(18,8,18,8);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,58);p.setMargins(18,8,18,8);b.setLayoutParams(p);return b;}
    void build(){
      ScrollView sv=new ScrollView(this); root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(18,22,18,30);root.setBackgroundColor(BG);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);sv.addView(root);setContentView(sv);
      TextView logo=tv("عَهدي 90",30,DARK,true);root.addView(logo);root.addView(tv("90 يومًا من الالتزام — يوم واحد في كل مرة",15,MUTED,false));
      LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(14,16,14,16);card.setBackground(bg(Color.WHITE,30));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,22,0,10);card.setLayoutParams(cp);root.addView(card);
      dayTitle=tv("",22,DARK,true);card.addView(dayTitle);status=tv("",17,MUTED,false);card.addView(status);markBtn=btn("أتممت عهدي ✓");card.addView(markBtn);markBtn.setOnClickListener(v->toggleToday());
      progress=tv("",15,MUTED,false);card.addView(progress);streak=tv("",17,GREEN,true);card.addView(streak);
      root.addView(tv("تقويم العهد",22,DARK,true));grid=new GridLayout(this);grid.setColumnCount(7);grid.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));root.addView(grid);fillGrid(grid);
      rewardTitle=tv("🎁 المكافآت الأسبوعية",22,DARK,true);rewardTitle.setPadding(12,28,12,8);root.addView(rewardTitle);rewardsBox=new LinearLayout(this);rewardsBox.setOrientation(LinearLayout.VERTICAL);root.addView(rewardsBox);showRewardCards();
      Button settings=btn("⚙️ إعدادات التذكير");root.addView(settings);settings.setOnClickListener(v->showSettings());
      TextView note=tv("تذكّر: يوم ناقص لا يعني رحلة ناقصة. عُد اليوم وكمل.",14,MUTED,false);note.setPadding(12,20,12,4);root.addView(note);refresh();
    }
    void fillGrid(GridLayout grid){for(int i=1;i<=90;i++){final int d=i;TextView x=tv(String.valueOf(i),13,Color.WHITE,true);x.setGravity(Gravity.CENTER);x.setPadding(0,0,0,0);GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=46;p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.setMargins(3,3,3,3);x.setLayoutParams(p);x.setOnClickListener(v->showDay(d));grid.addView(x);} }
    void paintGrid(){ if(grid==null)return; int cur=AppData.dayIndex(this,LocalDate.now()); for(int i=1;i<=90;i++){TextView x=(TextView)grid.getChildAt(i-1); if(AppData.marked(this,i)) x.setBackground(bg(GREEN,18)); else if(i==cur) x.setBackground(bg(GOLD,18)); else x.setBackground(bg(Color.rgb(170,178,172),18));}}
    void refresh(){LocalDate today=LocalDate.now();int idx=AppData.dayIndex(this,today); if(idx<1)idx=1;if(idx>90)idx=90;dayTitle.setText("اليوم "+idx+" من 90");status.setText(DateTimeFormatter.ofPattern("EEEE، d MMMM yyyy",new Locale("ar")).format(today));boolean done=AppData.marked(this,idx);markBtn.setText(done?"✓ تم وضع العهد اليوم":"أتممت عهدي ✓");markBtn.setAlpha(done?0.72f:1f);progress.setText("أنجزت: "+AppData.total(this)+" / 90 يوم");streak.setText("🔥 سلسلة الالتزام: "+AppData.streak(this)+" يوم"); paintGrid();}
    void toggleToday(){int idx=AppData.dayIndex(this,LocalDate.now());if(idx<1||idx>90)return;AppData.setMarked(this,idx,!AppData.marked(this,idx));refresh();showRewardCards();}
    void showDay(int d){new AlertDialog.Builder(this).setTitle("اليوم "+d).setMessage(AppData.marked(this,d)?"✅ هذا اليوم مكتمل.":"⬜ لم يتم وضع العلامة لهذا اليوم.").setPositiveButton("حسنًا",null).show();}
    void showRewardCards(){ if(rewardsBox==null)return; rewardsBox.removeAllViews(); for(int w=1;w<=12;w++){ LinearLayout card=new LinearLayout(this); card.setOrientation(LinearLayout.VERTICAL); card.setPadding(14,12,14,12); card.setBackground(bg(Color.WHITE,24)); LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2); cp.setMargins(0,5,0,5); card.setLayoutParams(cp); boolean done=AppData.weekComplete(this,w); TextView h=tv((done?"🔓":"🔒")+" الأسبوع "+w,18,done?GREEN:MUTED,true); card.addView(h); TextView body=tv(done?"مكافأتك مفتوحة 🎁 — تذكير الأسبوع: الثبات أهم من الحماس.":"أكمل الأيام "+((w-1)*7+1)+"–"+Math.min(w*7,90)+" لفتح المكافأة.",14,MUTED,false); card.addView(body); if(done){Button b=btn("▶ مشاهدة المكافأة"); b.setOnClickListener(v->showReward(w)); card.addView(b);} rewardsBox.addView(card);} }
    void showReward(int w){ String[] msgs={"ابدأ بالقليل، واثبت عليه. الأعمال أحب إلى الله أدومها وإن قل.","حين تتعب، تذكّر لماذا بدأت. الثبات عبادة للنفس قبل أن يكون إنجازًا.","لا تنتظر الحماس؛ ابنِ عادة تستطيع الاستمرار عليها.","كل صباح فرصة جديدة لتجديد النية.","التقدم البطيء ما زال تقدمًا. لا تحتقر خطوة صغيرة.","اجعل هدفك اليوم فقط: أن تفي بعهد اليوم.","إذا سقطت، قم سريعًا. الاستسلام هو الخسارة الحقيقية.","قوة الإنسان تظهر في لحظة الاختيار الصعب.","الانضباط أن تفعل الصواب حتى عندما لا تشعر بالرغبة.","أكمل الطريق؛ ما بقي أقل مما قطعته.","اقتربت من النهاية. لا تترك آخر الأمتار.","90 يومًا لا تغيّر يومك فقط؛ قد تغيّر علاقتك بنفسك."}; new AlertDialog.Builder(this).setTitle("🎁 مكافأة الأسبوع "+w).setMessage(msgs[w-1]).setPositiveButton("الحمد لله، أواصل",null).show(); }
    void showSettings(){
      LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(35,15,35,10);int rh=getSharedPreferences(AppData.PREF,0).getInt("rem_hour",7), rm=getSharedPreferences(AppData.PREF,0).getInt("rem_min",0); TextView t=tv(String.format(Locale.getDefault(),"وقت التذكير الحالي: %02d:%02d",rh,rm),17,DARK,false);box.addView(t);TimePicker tp=new TimePicker(this);tp.setIs24HourView(false);tp.setHour(rh);tp.setMinute(rm);box.addView(tp);
      new AlertDialog.Builder(this).setTitle("تذكير صباحي").setView(box).setPositiveButton("حفظ",(d,w)->{getSharedPreferences(AppData.PREF,0).edit().putInt("rem_hour",tp.getHour()).putInt("rem_min",tp.getMinute()).apply(); ReminderScheduler.schedule(this);Toast.makeText(this,"تم حفظ التذكير اليومي 🌅",Toast.LENGTH_SHORT).show();}).setNegativeButton("إلغاء",null).show();
    }
    @Override protected void onResume(){super.onResume();if(root!=null)refresh();}
}
